  if (!submission) {
    teacherStudentName.textContent = "Selecione um envio";
    teacherProblemTitle.textContent = "-";
    teacherSubmissionStatus.textContent = "sem sele\xe7\xe3o";
    teacherSubmissionStatus.dataset.kind = "neutral";
