  const labels = { RECEIVED: "Recebida pelo ConfIA", DRAFT: "Rascunho da transcri\xe7\xe3o", NEEDS_REVIEW: "Aguardando confer\xeancia", ACCEPTED: "Transcri\xe7\xe3o conferida" };
  const statusLabel = (status) => labels[status] || "Estado indispon\xedvel";
  const validId = (id) => typeof id === "string" && /^sub_[0-9a-f]{32}$/.test(id);
  const when = (value) => new Date(value).toLocaleString("pt-BR");

  function node(tag, content) {
    const value = document.createElement(tag);
    if (content !== undefined) value.textContent = content;
    return value;
  }

  function labeled(text, control) {
    const label = node("label");
    label.appendChild(node("span", text));
    label.appendChild(control);
    return label;
  }

  function option(value, text) {
    const item = node("option", text);
    item.value = value;
    return item;
  }

  async function request(url, options = {}) {
    const response = await fetch(url, { cache: "no-store", ...options });
    if (!response.ok) {
      let diagnostic = null;
      try {
        diagnostic = await response.json();
      } catch (_error) {
        // Keep the status available in the diagnostic log.
      }
      const error = new Error(`HTTP ${response.status}`);
      error.status = response.status;
      error.diagnostic = diagnostic;
      throw error;
    }
    return response.json();
  }

  const auditErrors = {
    TRANSCRIPTION_NOT_ACCEPTED: "A transcri\xe7\xe3o precisa ser conferida antes da an\xe1lise.",
    SOURCE_INTEGRITY_MISMATCH: "A fonte desta an\xe1lise n\xe3o passou na verifica\xe7\xe3o de integridade.",
    RESULT_INTEGRITY_MISMATCH: "N\xe3o foi poss\xedvel validar a integridade do resultado desta an\xe1lise.",
    REPRODUCIBILITY_INTEGRITY_MISMATCH: "N\xe3o foi poss\xedvel validar os metadados desta an\xe1lise.",
    REVISION_CONFLICT: "Existe uma revis\xe3o mais recente ou um aceite de outra revis\xe3o. Atualize a solu\xe7\xe3o.",
    AUDIT_RUN_CONFLICT: "N\xe3o foi poss\xedvel recuperar esta an\xe1lise. Atualize a solu\xe7\xe3o ou execute uma nova an\xe1lise.",
  };
  const safeErrorCode = error => Object.hasOwn(auditErrors, error?.diagnostic?.error_code)
    ? error.diagnostic.error_code : null;

  function productError(error, action = "load") {
    console.error("ConfIA: manuscritos/transcri\xe7\xe3o", action, error.status, safeErrorCode(error));
    if (safeErrorCode(error)) return auditErrors[safeErrorCode(error)];
    if (action === "audit" && error.status === 409) {
      const diagnostic = String(error.diagnostic?.detail || "");
      if (/metadados|manifesto/i.test(diagnostic)) return auditErrors.REPRODUCIBILITY_INTEGRITY_MISMATCH;
      if (/integridade|arquivos originais/i.test(diagnostic)) return auditErrors.SOURCE_INTEGRITY_MISMATCH;
      if (/transcri\xe7\xe3o.*conferida/i.test(diagnostic)) return auditErrors.TRANSCRIPTION_NOT_ACCEPTED;
      if (/result_sha256/i.test(diagnostic)) return auditErrors.RESULT_INTEGRITY_MISMATCH;
      return auditErrors.AUDIT_RUN_CONFLICT;
    }
    if (/integridade da revis\xe3o ou do aceite/i.test(JSON.stringify(error.diagnostic || {}))) {
      return action === "audit" ? "A integridade da revis\xe3o ou do aceite est\xe1 divergente. A an\xe1lise foi bloqueada."
        : "A integridade da revis\xe3o ou do aceite est\xe1 divergente. Reabra a solu\xe7\xe3o para conferir o hist\xf3rico.";
    }
    if (action === "audit") {
      const diagnostic = JSON.stringify(error.diagnostic || {});
      if (/arquivos originais/i.test(diagnostic)) return "Os arquivos originais desta solu\xe7\xe3o precisam ser conferidos.";
      if (/transcri\xe7\xe3o.*conferida/i.test(diagnostic)) return "A transcri\xe7\xe3o precisa ser conferida antes da an\xe1lise.";
      return "N\xe3o foi poss\xedvel concluir a An\xe1lise ConfIA.";
    }
    if (error.status === 404) return "N\xe3o foi poss\xedvel carregar esta solu\xe7\xe3o. Ela pode n\xe3o estar mais dispon\xedvel. Atualize a lista e tente novamente.";
    if (error.status === 409) {
      const diagnostic = JSON.stringify(error.diagnostic || {});
      if (/integridade|artefato|integrity|hash|artifact|snapshot|png/i.test(diagnostic)) return "Os arquivos originais desta solu\xe7\xe3o precisam ser conferidos. Reabra a solu\xe7\xe3o e consulte a integridade dos arquivos.";
      return "Existe uma revis\xe3o mais recente da transcri\xe7\xe3o. Salve uma c\xf3pia das suas altera\xe7\xf5es e reabra a solu\xe7\xe3o para conferir o hist\xf3rico.";
    }
    if (action === "recognize") return "N\xe3o foi poss\xedvel gerar a transcri\xe7\xe3o autom\xe1tica. Nenhuma transcri\xe7\xe3o criada. Tente novamente.";
    if (action === "save") return "N\xe3o foi poss\xedvel salvar a transcri\xe7\xe3o agora. Suas altera\xe7\xf5es continuam nesta tela. Confira os campos e tente novamente.";
    if (action === "accept") return "N\xe3o foi poss\xedvel registrar a confer\xeancia desta transcri\xe7\xe3o. Reabra e tente novamente.";
    return "N\xe3o foi poss\xedvel consultar as solu\xe7\xf5es agora. Atualize a lista e tente novamente.";
  }

  function canLeaveEditor() {
    if (activeDecision?.busy || activeDecision?.isDirty()) {
      message.textContent = activeDecision.busy ? "Aguarde a opera\xe7\xe3o da decis\xe3o terminar."
        : "Salve ou descarte as altera\xe7\xf5es da decis\xe3o antes de trocar o contexto.";
      message.focus();
      return false;
    }
    if (!activeEditor) return true;
    if (activeEditor.busy) {
      message.textContent = "Aguarde a opera\xe7\xe3o desta transcri\xe7\xe3o terminar antes de trocar o contexto.";
      message.focus();
      return false;
    }
    if (!activeEditor.isDirty()) return true;
    message.textContent = "Altera\xe7\xf5es n\xe3o salvas. Salve uma nova revis\xe3o ou use “Descartar altera\xe7\xf5es n\xe3o salvas” antes de trocar o contexto.";
    message.focus();
    return false;
  }

  function write(url, body) {
    return request(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
  }

  function integrityDetails(data, id) {
    const record = data.submission;
    const hashes = node("details");
    hashes.className = "disclosure";
    hashes.appendChild(node("summary", "Integridade dos arquivos"));
    hashes.appendChild(node("p", "Hashes indicam somente integridade t\xe9cnica; n\xe3o comprovam autoria nem validade matem\xe1tica."));
    const items = node("ul");
    for (const artifact of data.integrity) {
      items.appendChild(node("li", `${artifact.filename}: ${artifact.matches ? "confere" : "divergente/ausente"} \xb7 SHA-256 esperado: ${artifact.expected_sha256} \xb7 atual: ${artifact.actual_sha256 || "ausente"}`));
    }
    hashes.appendChild(items);
