    const source = captureDocument;
    renderState();
    try {
      await persist(source, { announce: false });
      const snapshot = Model.freeze(source);
      await Store.save(snapshot);
      if (captureDocument !== source) return;
      setDocument(snapshot, pageIndex);
      elements.storageState.textContent = "C\xf3pia congelada neste dispositivo";
      setPersistenceState("saved");
      elements.snapshotMessage.textContent = "Vers\xe3o preparada localmente. Envie para confirmar o recebimento.";
      setStatus("A c\xf3pia congelada foi salva localmente. Use Enviar solu\xe7\xe3o para solicitar recebimento pelo servidor.", "saved");
      await refreshSavedDocuments();
