  }
  async function recognizeSubmittedSnapshot(snapshotId, receipt) {
    if (!receipt?.submission_id || recognitionBusy.has(receipt.submission_id)) return;
    const state = recognitionStates.get(snapshotId) || { attempt: 0 };
    recognitionBusy.add(receipt.submission_id);
    state.segments = [];
    state.failed = false;
    state.message = "Reconhecendo a solu\xe7\xe3o enviada...";
    recognitionStates.set(snapshotId, state);
    renderSubmission();
    try {
      const response = await fetch(tmeCasePath ? `${tmeCasePath}/recognize` : `/submissions/${encodeURIComponent(receipt.submission_id)}/recognitions`, {
        method: "POST", headers: { "Content-Type": "application/json" }, cache: "no-store",
        body: JSON.stringify({ provider: "mathpix", idempotency_key: `mathpix:${state.attempt}` }),
      });
      if (!response.ok) throw new Error("Reconhecedor indispon\xedvel. Confira a configura\xe7\xe3o do servidor.");
      const summary = await response.json();
      if (summary.status !== "NEEDS_REVIEW") {
        if (summary.status === "FAILED") state.attempt += 1;
        throw new Error("O reconhecimento falhou. Toque novamente para tentar uma nova leitura.");
      }
      const detail = await fetch(`${tmeCasePath || `/submissions/${encodeURIComponent(receipt.submission_id)}`}/recognitions/${encodeURIComponent(summary.recognizer_run_id)}`, { cache: "no-store" });
      if (!detail.ok) throw new Error("A transcri\xe7\xe3o foi registrada, mas n\xe3o p\xf4de ser carregada. Toque novamente para recuper\xe1-la.");
      const run = await detail.json();
      if (run.status !== "NEEDS_REVIEW" || !Array.isArray(run.result?.segments)) throw new Error("Transcri\xe7\xe3o autom\xe1tica indispon\xedvel.");
      state.segments = run.result.segments;
      state.message = tmeCasePath ? "Transcri\xe7\xe3o autom\xe1tica dispon\xedvel para an\xe1lise." : `Transcri\xe7\xe3o autom\xe1tica criada \xb7 aguarda confer\xeancia do ${recipient}.`;
      const submission = submissionStates.get(snapshotId);
      if (submission?.receipt?.submission_id === receipt.submission_id) {
        submissionStates.set(snapshotId, { ...submission, message: tmeCasePath ? "Solu\xe7\xe3o enviada. Transcri\xe7\xe3o autom\xe1tica dispon\xedvel." : `Solu\xe7\xe3o enviada ao ${recipient}. Transcri\xe7\xe3o autom\xe1tica aguarda confer\xeancia.`, kind: "saved" });
      }
    } catch (_error) {
      state.failed = true;
      state.message = "N\xe3o foi poss\xedvel gerar a transcri\xe7\xe3o autom\xe1tica. Toque para tentar novamente.";
      const submission = submissionStates.get(snapshotId);
      if (submission?.receipt?.submission_id === receipt.submission_id) {
        submissionStates.set(snapshotId, { ...submission, message: `Solu\xe7\xe3o enviada ao ${recipient}. N\xe3o foi poss\xedvel gerar a transcri\xe7\xe3o autom\xe1tica.`, kind: "error" });
      }
    } finally {
      recognitionBusy.delete(receipt.submission_id);
      renderSubmission();
      if (tmeCasePath && embedded) globalThis.parent.postMessage({
        type: "confia-notebook-context", context: { tmeRecognitionFinished: true, receipt },
      }, globalThis.location.origin);
    }
