      if (/transcri\xe7\xe3o.*conferida/i.test(diagnostic)) return "A transcri\xe7\xe3o precisa ser conferida antes da an\xe1lise.";
      return "N\xe3o foi poss\xedvel concluir a An\xe1lise ConfIA.";
